<?php
require $argv[1].'/wp-load.php';
function c8_read($path,$params=[]){$request=new WP_REST_Request('GET',$path);foreach($params as $k=>$v){$request->set_param($k,$v);}$r=rest_do_request($request);return ['code'=>$r->get_status(),'data'=>rest_get_server()->response_to_data($r,false),'headers'=>$r->get_headers()];}
$manifest=json_decode(file_get_contents($argv[2]),true,512,JSON_THROW_ON_ERROR);$roles=['administrator','author','contributor','subscriber','editor'];$users=[];
foreach($roles as $role){$login='c8-'.$role;$id=wp_create_user($login,'disposable-fixture-password',$login.'@example.invalid');if(is_wp_error($id)){$id=username_exists($login);}if(!$id){throw new RuntimeException('Cannot seed fixture');}(new WP_User($id))->set_role($role);wp_update_user(['ID'=>$id,'display_name'=>$role,'user_nicename'=>$login]);$users[$role]=(int)$id;}
foreach([['author','post','publish'],['editor','page','publish'],['administrator','post','draft'],['contributor','post','draft']] as [$role,$type,$status]){$r=wp_insert_post(['post_title'=>'c8-'.$role,'post_name'=>'c8-'.$role,'post_type'=>$type,'post_status'=>$status,'post_author'=>$users[$role]],true);if(is_wp_error($r)){throw new RuntimeException('Cannot seed article');}}
$details=[];foreach(array_merge(['anonymous'],$roles) as $actor){wp_set_current_user($actor==='anonymous'?0:$users[$actor]);foreach($roles as $target){foreach(['view','embed','edit'] as $context){$details[]=['actor'=>$actor,'target'=>$target,'context'=>$context,'result'=>c8_read('/wp/v2/users/'.$users[$target],['context'=>$context])];}}}
$me=[];foreach(array_merge(['anonymous'],$roles) as $actor){wp_set_current_user($actor==='anonymous'?0:$users[$actor]);foreach(['view','embed','edit'] as $context){$me[]=['actor'=>$actor,'context'=>$context,'result'=>c8_read('/wp/v2/users/me',['context'=>$context])];}}
$queries=[];foreach($manifest['queries'] as $q){$params=$q['params'];if(!isset($params['include'])&&!isset($params['exclude'])){$params['include']=array_values($users);}else{foreach(['include','exclude'] as $key){if(isset($params[$key])){$params[$key]=array_map(fn($role)=>$users[$role],$params[$key]);}}}if(isset($params['slug'])){$params['slug']=array_map(fn($role)=>'c8-'.$role,$params['slug']);}if(($params['search']??'')==='$subscriber_id'){$params['search']=(string)$users['subscriber'];}if(!isset($params['search'])){$params['search']='c8-';}wp_set_current_user($q['actor']==='anonymous'?0:$users[$q['actor']]);$queries[]=['query'=>$q,'result'=>c8_read('/wp/v2/users',$params)];}
file_put_contents($argv[3],json_encode(['users'=>$users,'details'=>$details,'me'=>$me,'queries'=>$queries],JSON_THROW_ON_ERROR));
